from collections import defaultdict

def find_tree(pre_order, constraints):
    num_of_nodes = len(pre_order)
    if num_of_nodes < 2:
        return "IMPOSSIBLE"

    tree = [i + 1 for i in range(num_of_nodes)]

    for constraint in constraints:
        a, b, direction = constraint[0] - 1, constraint[1] - 1, constraint[2]

        if direction == 'LEFT':
            if tree[a] not in pre_order[b-1:] or tree[a] == b:
                return "IMPOSSIBLE"
            tree[a-1:b] = tree[b-1:a], 2 * (b-1 - a) + subtree_size(tree, b)
        else:
            if tree[a] not in pre_order[b-1:] or tree[a] == b:
                return "IMPOSSIBLE"
            tree[a-1:b] = tree[a-2*b] + (2 * (a - b)), subtree_size(tree, a)

        if a == 0:
            return tree[1:]

    return tree[1:]

def subtree_size(subtree, root):
    size = 0
    for i, node in enumerate(subtree):
        if node > root:
            size += 1
            size += subtree_size(subtree[i:], root)
            if i > 0:
                subtree[i-1] = subtree[i]
            if i < len(subtree) - 1:
                subtree[i + 1:i+1] = subtree[i:]
                subtree[i] = root + size
                root += size
    return size

