        self.right = None

def validate_tree(nodes: List[int], constraints: List[Tuple[int, int, str]]) -> bool:
    graph = defaultdict(list)
    for ai, bi, direction in constraints:
        if direction == "LEFT":
            graph[ai].append(bi)
        else:
            graph[ai].append(bi)
    leaves = set()

    def validate_tree_helper(node: TreeNode | None) -> bool:
        if node is None:
            return True
        if len(graph[node.label]) == 0:
            if node.label in leaves:
                return False
        for neighbor in graph[node.label]:
            if not validate_tree_helper(TreeNode(neighbor)):
                return False
        leaves.add(node.label)
        return True

    if not validate_tree_helper(TreeNode(min(nodes))):
        return False
    return True

