import numpy as np

class QueryHandler:
    def __init__(self):
        self.last_update = 0
        self.data = []
        self.mask = np.uint32(0xffffffff)

    def process_query_update(self, query_type, l, r, value):
        new_l, new_r, new_x = l, r, value
        self.last_update = new_x
        # Update the ranges merge intervally
        half = 1
        while half < new_l:
            new_l += half
            half *= 2
        while half < new_r + 1:
            new_r += half
            half *= 2
        if new_r < new_l:
            new_l, new_r = new_r, new_l

        # Perform XOR operations
        operation = self.mask ^ new_x
        offset = self.mask ^ (new_x - self.last_update)
        self.data = [operation | data & offset for data in self.data]

    def process_query(self, query_type, l, r):
        l_update, r_update = l | self.last_update, r | self.last_update
        # Perform XOR operations
        result = 0
        for i in range(l_update, r_update + 1):
            result ^= self.data[i]

        # Check if the value is updated
        if l_update == r_update:
            result ^= (self.mask ^ self.last_update)

        if result == self.mask:
            result = -1

        return result


def solve(input_queries):
    query_handler = QueryHandler()
    for query in input_queries:
        query_type, l, r = query.split()
