def all_divisors(n):
    factors = {}
    rng = int(n ** 0.5) + 1
    for divisor in range(2, rng):
        if n % divisor == 0:
            factors[divisor] = 0
            while n % divisor == 0:
                n //= divisor
                factors[divisor] += 1
            if divisor != n:
                factors[n] = 0
                while n % divisor == 0:
