def count_good_messages(A):
    n = len(A)
    cyclic_shifts = defaultdict(set)
    for a in A:
        for p in range(n):
            cs = set()
            for i in range(p, n, p+1):
                cs.add(f"{A[i]}")
            cyclic_shifts[a].update(cs)

    good_messages = set()
    for a in A:
        for p in range(n):
            for i in range(p, n, p+1):
                good_messages.add(f"{A[p]}{''.join(a)}{''.join(cyclic_shifts[a][:p])}")

    good_count = sum(1 for g in good_messages if len(g).count(" ") == 2)

    return good_count

