            new_dp_table[(card[0] + (max(card[0] + card[1] + (n - i) - 1, 0) if i + 1 < n else 0), 0)], \
            new_dp_table[(max(card[0] + card[1] + (n - i) - 1, 0), card[2])] = (i + 1), val + 1
