class BitwiseXorTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (2 * n + 1)
        self.ctr = [0] * (2 * n + 1)

    def update(self, i, v):
        i += self.n
        self.ctr[i] = v
        while i > 1:
            i >>= 1
            self.tree[i] = self.tree[i * 2] ^ self.tree[i * 2 + 1]

    def query(self, l, r):
        if l == r:
            return 0
        l += self.n, r += self.n
        res = 0
        while l < r:
            if l & 1:
                res ^= self.tree[l]
                l += 1
            if r & 1:
                res ^= self.tree[r - 1]
                r -= 1
            l >>= 1
            r >>= 1
        return res

