class BitwiseXorTree:
    def __init__(self, max_size):
        self.tree = [0] * (max_size * 4)

    def build(self, nums):
        n = len(nums)
        self.tree[1] = nums
        for i in range(2, len(self.tree)):
            self.tree[i] = self.tree[i // 2] ^ self.tree[i // 2 + 1]
        return self.tree

    def update(self, l, r, x, tree_idx):
        l = (l + self.tree_idx) % self.tree_idx
        r = (r + self.tree_idx) % self.tree_idx
        x = (x + self.tree_idx) % self.tree_idx
        self.tree[tree_idx] = x
        while l < r:
            if l & 1:
                self.tree[tree_idx] ^= self.tree[l]
                l += 1
            if r & 1:
                r -= 1
                self.tree[tree_idx] ^= self.tree[r]
            l >>= 1
            r >>= 1
        return self.tree[tree_idx]

    def get_xor(self, l, r, tree_idx):
        l_bin, r_bin = (l + tree_idx) & tree_idx, (r + tree_idx) & tree_idx
        x = 0
        while l_bin > 0 or r_bin > 0:
            if l_bin & 1:
                x ^= self.tree[tree_idx]
            if r_bin & 1:
                x ^= self.tree[tree_idx]
            l_bin = l_bin >> 1
            r_bin = r_bin >> 1
            tree_idx >>= 1
        return x ^ self.tree[tree_idx], x

def solve_queries(nums, queries):
    max_size = 1
    while (1 << max_size) < len(nums):
        max_size += 1
    tree = BitwiseXorTree(max_size)

    tree.tree = tree.build(nums)

    for query in queries:
        query_type = query[0]
        if query_type == 1:
            l, r, x = query[1], query[2], query[3]
            l_prime = l ^ tree.tree_query_lonly(l)
            r_prime = r ^ tree.tree_query_lonly(r)
            x_prime = x ^ tree.tree_query_lonly(x)
            l, r, x = l_prime, r_prime, x_prime
        elif query_type == 2:
            l, r = query[1], query[2]
            xor, left = tree.tree_query_lonly(l)
            right = query[0] ^ xor
            td = right - left
            condition = 0 <= right < len(nums)
            return -1 if not condition or (xor & right) == 0 else td
        tree.tree = tree.update(l, r, x, tree.tree_idx)
    return tree.get_xor(l, r, tree.tree_idx)

def tree_query_lonly(q, tree):
    if q == 0:
        return -1
    return tree.tree[q]

