def lucky_ways(n, m, w, queries):
    input_sum = [0] * (n + 1)
    input_minus = [0] * (n + 1)
    result = [0] * m

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if w[i - 1][j - 1]:
                input_sum[i - 1] += 1
            input_minus[i - 1] += 1

    for i in range(1, n + 1):
        input_minus[i - 1] = input_minus[i - 1] - input_sum[i - 1]

    for i, num in queries:
        if num not in range(1, 4):
            continue
        if num + n - i <= n:
            side = num - 1
        else:
            side = num - 4
        diff = 0 if num - 1 <= side else input_minus[n - i]
        for j in range(1, side + 1):
            diff = diff - input_sum[i - 1 - j]
        for j in range(1, n - i - side - 1):
            diff = diff + input_sum[n - i - side + j]

        result[i - 1] = 777777777 % (pow(2, diff, 777777777) - 1)

    return result

