def find_cyclic_shifts(s, n_str):
    # Calculate the length of the string s
    s_len = len(s)
    shift_count = 0
    for i in range(n_str):
        if i + 1 <= s_len - n_str:
            if s[:n_str] == s[i:i+n_str]:
                shift_count += 1
    return shift_count

def is_good_message(m):
    n_str = len(m)
    shift_count = 0
    for start in range(n_str):
        cyclic_shifts = find_cyclic_shifts(m, start)
        if cyclic_shifts == start + 1:
            shift_count += 1
    return shift_count == n_str

def is_stable_list(X):
    for i in range(len(X)):
        if not is_good_message(X[i]):
            return False
    return True

