def calculate_min_cost(n, m, rectangles):
    # Store the positions of black cells
    black_cells = {(x, y) for rect in rectangles for x1, y1, x2, y2 in [rect] + [[max(r[0], rect[0]), max(r[1], rect[1]), min(r[2], rect[2]), min(r[3], rect[3])] for r in rectangles[1:]]}

    # Initialize the DP table
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    # DP Main Loop
    for x in range(1, n + 1):
        temp_dp = dp[:]
        for y in range(n - x + 1):
            for black_cell in black_cells:
                found_black = False
                for black_x in range(black_cell[0], black_cell[0] + x):
                    if (black_cell[0], black_cell[1] + y) not in black_cells:
                        for black_y in range(black_cell[1], black_cell[1] + y):
                            if (black_x, black_y) in black_cells:
                                found_black = True
                                break
                        if found_black:
                            break
                if not found_black:
                    dp[y + x] = min(dp[y + x], dp[y] + x)
        dp = temp_dp

    return min(dp)

