def is_robot_driver(pairs):
    road_graph = defaultdict(list)
    in_degree = defaultdict(int)

    for pair in pairs:
        a, b = pair[0], pair[1]
        in_degree[b] += 1
        road_graph[a].append((b, pair[2]))
        road_graph[b].append((a, pair[2]))

    component_edges = defaultdict(list)

    for node in range(1, len(road_graph) + 1):
        if in_degree[node] == 1:
            if len(component_edges[node]) == 0:
                for child, direction in road_graph[node]:
                    component_edges[node].append((child, direction))
            continue

        for child, direction in road_graph[node]:
            comp_child = child if direction else road_graph[child][0][0]
            component_edges[comp_child].append((node, direction))

    can_deflect = False

    for edge in component_edges.values():
        if len(set(map(lambda x: x[1], edge))) < 2:
            can_deflect = True

    return not can_deflect

