import collections
from typing import List

def is_robot_driver(rides: List[List[int]]) -> str:
    # nx2 edge list for undirected graph
    graph = [set() for _ in range(len(rides))]

    for i in range(1, len(rides)):
        a, b = rides[i-1][0], rides[i][0]
        c1, c2 = rides[i-1][1], rides[i][1]
        if a == c1:
            if len(graph[i-1]) != 1 or len(graph[b]) != 1:
                return "Not enough edges for cycle"
            graph[c1].add(b)
            graph[b].add(c1)
        elif b == c1:
            if len(graph[i-1]) != 1 or len(graph[a]) != 1:
                return "Not enough edges for cycle"
            graph[c1].add(a)
            graph[a].add(c1)
        elif a == c2:
            if len(graph[i-1]) != 1 or len(graph[b]) != 1:
                return "Not enough edges for cycle"
            graph[c2].add(b)
            graph[b].add(c2)
        elif b == c2:
            if len(graph[i-1]) != 1 or len(graph[a]) != 1:
                return "Not enough edges for cycle"
            graph[c2].add(a)
            graph[a].add(c2)

    # Check connectivity and cycles for all nodes
    for i in range(len(graph)):
        visited = set()
        if len(graph) == 1:
            return "Identical"
        if not graph[i]:
            return "Robot"
        stack = [i]
        while stack:
            node = stack.pop()
            if node in visited:
                return "Not connected" if len(graph) != 1 else "Cycle"
            visited.add(node)
            for neighbor in graph[node]:
                stack.append(neighbor)
        return "Robot"

