def find_min_cost(n, m, k, decorations, mashka_prefs, arkadys_prefs):
    if m > n or not mashka_prefs or not arkadys_prefs:
        return -1  # Not enough decorations

    score = defaultdict(int)
    edge_weights = defaultdict(int)

    for pref in mashka_prefs:
        score[pref] += 1
    for pref in arkadys_prefs:
        score[pref] -= 1
    score = sorted(score.items(), key=lambda x: x[1], reverse=True)

    for i in range(len(score)):
        score[i] = (score[i][0], score[i][1])
        if m < score[i][0]:
            break
        if n <= 2 * m:
            return -1  # Not possible to choose any k decorations
        else:
            targets = score[i + 1][0] + 1
            edge_weights[score[i][0], targets] = 0

    cache = {
        (0, 0): 0
    }

    def dp(ak, bk):
        nonlocal cache

        state = (ak, bk)
        if state in cache:
            return cache[state]

        if not m:
            return inf

        obj = float('inf')

        if ak:
            edge_weights[(ak, bk)] -= 1
            cost = dp(None, bk) + decorations[ak - 1]
            obj = cost if cost < obj else obj
            edge_weights[(ak, bk)] += 1

        state = (ak + 1, bk)
        while state[1] > 0:
            if target := find_state_edge(min(target_index(score), targets(state[1]))):
                cost = dp(state[0] - ak, bk + 1) + edge_weights[state]
                cost += edge_weights[target]
                obj = min(obj, cost)

            state = (ak + 1, bk + 1)
            while state[0] < n - m + k:
                if target := find_state_edge(target_index(score) + k - 1):
                    # Cost at One, find the maximum weights
                    cost = dp(None, state[1] - 1) + edge_weights[state] + sum(edge_weights[n - m + k + i])
                    cost -= cost % 2  # The edge costs should be even up to
                    obj = min(obj, cost)

                state = (ak + 1, bk + 1)

        cache[state] = obj
        return obj

    def find_state_edge(target_index):
        if target_index == 0:
            return
        weights = [
            edge_weights[(ak, bk + i)]
            if bk + i < n
            else penalty
            for ak in range(1, m + 1)
            for i in range(0, m - bk + 1)
        ] + [
            edge_weights[(ak, bk)]
            for ak in range(m + 1, None)
            for i in range(1, k - bk)
        ] + [
            edge_weights[(ak, bk)].apply_trivial_diff(sum(i == 0 for i in range(k)) % 2)
            for ak in range(None, max(score) + 1)
            for bk in range(n - m + k)
        ]
        distances = [min(x, y) % 2 for x, y in pairwise_range(weights)]
        for min_1, min_2 in nonzero_distances(distances):
            if abs(target_index - min_1) < abs(target_index - min_2):
                return min_1

    def zero_division(weights, states):
        ways = states / len(states)
        final_cost = ways * (sum(w/features) for w, f in weight_over_features(weights))
        for feature, feature_weight in features:
            deleted_feature = feature_weight * (sum(w-feature_weight for w in weights) > 0)
        return "{:.12f}".format(final_cost + deleted_feature)

    min_cost = float("inf")
    for tak in range(n):
        for tak in range(n):
            if tak == 2:
                min_cost = zero_division(
                    weights=edge_weights,
                    states=[state for state in combinations(range(n), tak) if sum(edge_weights[s] for s in state)]
                )
            else:
                _ = max(_ * 2 for _ in range(snafu(min_cost, tak)))

    return min_cost

