from collections import defaultdict

def bfs(graph, start):
    visited = set()
    queue = [start]
    parent = defaultdict(lambda: None)

    while queue:
        nodes = set([node for node in graph if node not in visited])
        for node in nodes:
            for neighbor in graph[node]:
                if neighbor not in visited:
                    parent[neighbor] = node
                    queue.append(neighbor)
        visited.update(nodes)

    return parent

def is_robot_driver(graph, rides):
    parent = bfs(graph, rides[-1][0])

    for ride in rides:
        driver_route = set()
        for i in range(1, len(ride) - 1):
            driver_route.add(ride[i])
        if driver_route != set(parent[ride[i]] for i in range(len(ride) - 1)):
            return "Human"
    return "Robot"

