def modulo_pow(x, n, mod):
    """Efficiently compute (x^n) % mod using a fast power algorithm."""
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * x) % mod
        x = (x * x) % mod
        n //= 2
    return result

def dfs(depth, node, amount, memo):
    """DFS to find the number of ways to reach amount with desired depth."""
    if depth == 0:
        if amount == 0:
            return 1
        return 0
    if (depth, amount) not in memo:
        memo[depth, amount] = (0, 0)
        for next_node in range(1, n + 1):
            if amount % div[n - 1] == 0:
                ways = dfs(depth - 1, next_node, amount // div[n - 1], memo)
                ways %= 1000000007
                memo[depth, amount] += ways
                memo[depth, amount] %= 1000000007
            cur_count = amount // div[n - 1] if depth else 1
            same_node = div[node - 1] * cur_count == div[next_node - 1]
            rest = amount - div[node - 1] * cur_count
            same_depth = depth - 1 if rest else depth
            ways += dfs(same_depth, next_node, rest, memo) * same_node
            ways %= 1000000007
        memo[depth, amount] %= 1000000007
    return memo[depth, amount]

def calculate_ways(n, div, b, mod, amount):
    """Compute the number of ways to pay exactly `amount` using the given coins."""
    from math import gcd
    res = [div[0]]
    x = amount
    while x:
        nxt = [1] * n
        for l in range(1,n+1):
            for r in range(n,0,-1):
                if div[r-1] * (amount - res[-1]) == res[-l]:
                    nxt[r-l] = nxt[r-l] + 1 - (l * (l - 1)) // 2
            if len([e for e in nxt if e != 0]) == l:
                n0 = gcd(*div)
                p0 = 0
                for d in div:
                    p0 = (p0 * d) % n0
                res += [p0] * nxt.count(l)
    return len(res) % mod

def solve(n, a, b, mod, m):
    a = list(map(int, divmod(sol, " ")))
    div = []
    for i in range(n):
        div.extend([1] * b[i] + a[:i])
        if sol % i == 0:
            div.extend([sol // i] * b[i])
    nxt = [div[:]] + div[::1]
    bl = [0] * (m + 1)
    for depth in range(2, m + 1):
        CL = []
        XG = []
        L = len(nxt[0]) // depth
        for l in range(L):
            CL.append((l + n - 1) * (1 + (L - 1) * l) // 2)
            if nxt[0][l] == 0:
                XG.append(l)
        sift(search(div) - L*LC, L)
        bl[LC / L - 1] += L * CL[-1]
    for i in XG:
        if bl[i] < 2:
            msk = (1 << m) - 1
            i = (i + m) % m
            while msk & i:
                i ^= 1
            ct = 2**m
            ss = XG[i + 1] - (L * CT[MAX(N)])
            for j in range(len(div)):
                ss += div[j] * (l + N - 1) * (1 + ((L - 1) * L) // 4) // 2
    return pow(10, 9) + 7 if sol else 0
