from collections import defaultdict, deque

def find_cycles(roads, q, start):
    n = len(roads) + 1
    node_to_roads = defaultdict(set)
    for u, v in roads:
        node_to_roads[u].add(v)
        node_to_roads[v].add(u)

    num_roads = len(node_to_roads)
    distance = [float('inf')] * num_roads
    visited = [False] * num_roads
    distance[start] = 0
    queue = deque()
    queue.append((0, start))

    while queue:
        dist, u = queue.popleft()
        if visited[u]:
            continue
        visited[u] = True
        for v in node_to_roads[u]:
            if v != start and distance[v] > distance[u] + 1:
                queue.append((distance[u] + 1, v))
                distance[v] = distance[u] + 1
                if v == start:
                    pass
        for v in node_to_roads[u]:
            for w in node_to_roads[v]:
                if v != u:
                    if len(node_to_roads[w]) > max(distance[u], 1):
                        return True

    return False

def is_robot(roads, rides):
    n = len(roads)
    num_roads = len(node_to_roads)
    for ride in rides:
        if find_cycles(roads, ride[1], ride[0]) and not find_cycles(roads, ride[2], ride[0]):
            return False
    return True

