from collections import deque

def is_possible(n, c, constraints):
    # Create a mapping of constraints to nodes
    constraint_map = {}
    for i in range(1, n+1):
        constraint_map[i] = []

    for ai, bi, direction in constraints:
        if direction == "LEFT":
            constraint_map[ai].append(bi)
        else:
            constraint_map[ai].append(n + bi)

    # Keep track of visited nodes and the number of left and right children
    visited = [False] * (n + 1)
    left_children = [0] * (n + 1)
    right_children = [0] * (n + 1)

    # Breadth-first search to find a valid tree
    queue = deque([1])
    queue_length = 1
    visited[1] = True

    while queue_length > 0:
        node = queue.popleft()
        queue_length -= 1
        visited[node] = True

        for child in constraint_map[node]:
            if not visited[child]:
                visited[child] = True
                queue.append(child)
                queue_length += 1

            if child < node:
                left_children[node] += 1
            else:
                right_children[node] += 1

            if left_children[node] > 2 or right_children[node] > 2:
                return False

        if left_children[node] < right_children[node]:
            return False

    return True

def get_inorder_traversal(root):
    stack = deque([root])
    inorder = []

    while stack:
        node = stack.pop()
        inorder.append(node)

        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)

    return " ".join(map(str, inorder))

n, c = map(int, input().split())
constraints = []
for _ in range(c):
    ai, bi, direction = map(int, input().split())
    constraints.append((ai, bi, direction))

if not is_possible(n, c, constraints):
    print("IMPOSSIBLE")
else:
    print(get_inorder_traversal(1))
