from itertools import permutations

def calculate_hamming_distance(a, b):
    return sum(x != y for x, y in zip(a, b))

def find_max_hamming_triples(W, m, k):
    max_hamming = 0
    for triple in permutations([i + 1 for i in range(m)], 3):
        hamming = calculate_hamming_distance(W[triple[0] - 1], W[triple[1] - 1]) \
                  + calculate_hamming_distance(W[triple[0] - 1], W[triple[2] - 1]) \
                  + calculate_hamming_distance(W[triple[1] - 1], W[triple[2] - 1])
        if hamming > max_hamming:
            max_hamming = hamming
    return max_hamming

def solve(W, m, log_n):
    sorted_strings = sorted(W, key=lambda w: (w[1:2].count('1'), w[2:]), reverse=True)
    global_vs_local_bits = [sorted_strings[3 * (i - 1)] for i in range(1, m + 1)]
    return find_max_hamming_triples(global_vs_local_bits, m, m)

def main():
    n, m = map(int, input().split())
    W = [input().split() for _ in range(m)]
    solve(W, n, m)

if __name__ == "__main__":
    main()
